[CmdletBinding()]
param([switch]$All,[switch]$Client,[switch]$Server,[switch]$ServerAdmin,[switch]$ScreenMedia,[switch]$Updater,[string]$DependencyRoot)
$ErrorActionPreference='Stop'
$root=$PSScriptRoot
if(-not($All-or$Client-or$Server-or$ServerAdmin-or$ScreenMedia-or$Updater)){$All=$true}
if($All){$Client=$true;$Server=$true;$ServerAdmin=$true;$ScreenMedia=$true;$Updater=$true}
if($ServerAdmin){$Server=$true}
function Run([string]$Name,[scriptblock]$Block){& $Block;if($LASTEXITCODE -ne 0){throw "$Name failed (exit $LASTEXITCODE)."}}
function Need([string]$Path){if(-not(Test-Path -LiteralPath $Path)){throw "Required file is missing: $Path"}}
Push-Location $root
try {
 $sourceVersion=(Select-String -LiteralPath '.\shared\VersionInfo.cs' -Pattern 'Display="([^"]+)"').Matches[0].Groups[1].Value
 if($sourceVersion -notmatch '^(?<base>\d+\.\d+\.\d+-dev)(?:\.\d+)?$'){throw "Expected a development base version in VersionInfo.cs; found '$sourceVersion'."}
 $baseVersion=$Matches['base'];$developmentRoot=Join-Path $root 'build\development';New-Item -ItemType Directory -Force -Path $developmentRoot|Out-Null
 $revisionPattern='^'+[regex]::Escape($baseVersion)+'\.(\d+)$'
 $revisions=@(Get-ChildItem -LiteralPath $developmentRoot -Directory | ForEach-Object {if($_.Name -match $revisionPattern){[int]$Matches[1]}})
 $nextRevision=1;if($revisions.Count){$nextRevision=([int](($revisions|Measure-Object -Maximum).Maximum))+1}
 while($true){$version="$baseVersion.$nextRevision";$out=Join-Path $developmentRoot $version;if(Test-Path -LiteralPath $out){$nextRevision++;continue};try{New-Item -ItemType Directory -Path $out -ErrorAction Stop|Out-Null;break}catch{if(Test-Path -LiteralPath $out){$nextRevision++;continue};throw}}
 $clientOut=Join-Path $out 'Client';$screenOut=Join-Path $out 'ScreenMedia';$serverOut=Join-Path $out 'Server';$adminOut=Join-Path $out 'ServerAdmin';$updaterOut=Join-Path $out 'Updater';$packageOut=Join-Path $out 'Package'
 $generatedVersionSource=Join-Path $out 'VersionInfo.cs'
 [System.IO.File]::WriteAllText($generatedVersionSource,"namespace PeerChat { public static class VersionInfo { public const string Display=`"$version`"; public const string ReleaseFolder=`"v$version`"; } }",[System.Text.UTF8Encoding]::new($false))
 $deps=if($DependencyRoot){$DependencyRoot}elseif($env:PEERCHAT_DEPENDENCY_ROOT){$env:PEERCHAT_DEPENDENCY_ROOT}else{'C:\Peerchatdep\deps'}
 $native=if($env:PEERCHAT_NATIVE_DEPENDENCY_ROOT){$env:PEERCHAT_NATIVE_DEPENDENCY_ROOT}else{'C:\Peerchatdep\native\mingw-x64-libdatachannel-c6696d1-opus-ddbe483-mbedtls-068ff08'}
 if(($Client-or$ScreenMedia)-and(-not(Test-Path -LiteralPath $deps))){throw "Shared dependency root unavailable: $deps"}
