 if($All){New-Item -ItemType Directory -Force -Path $packageOut|Out-Null;@('PeerChat.Desktop.exe','PeerChat.Core.dll','PeerChat.Desktop.exe.config','peerchat-client.ico','PeerChat.Updater.Core.dll','PeerChat.Updater.exe','PeerChat.Updater.exe.config')|%{Copy-Item "$clientOut\$_" $packageOut -Force};Copy-Item "$screenOut\PeerChat.ScreenMedia.dll" $packageOut -Force;$apm='C:\Peerchatdep\artifacts\audio-processing\webrtc-6cf6bcb-voice-presets\x64\PeerChat.AudioProcessing.dll';Need $apm;if((Get-FileHash $apm -Algorithm SHA256).Hash -ne 'C324896121259FBCE10C6B8B15995606378CF281EEDD7515F0B4680181A75A08'){throw 'APM hash mismatch.'};Copy-Item $apm $packageOut -Force;Copy-Item .\desktop\service-bootstrap.json $packageOut -Force;Copy-Item .\updater\update-feeds.json $packageOut -Force;& .\scripts\verify-client-native-dependencies.ps1 -ClientDirectory $packageOut -RequireScreenMedia;if($LASTEXITCODE -ne 0){throw 'Package dependency audit failed.'}}
 if($Client){$apm='C:\Peerchatdep\artifacts\audio-processing\webrtc-6cf6bcb-voice-presets\x64\PeerChat.AudioProcessing.dll';Need $apm;if((Get-FileHash $apm -Algorithm SHA256).Hash -ne 'C324896121259FBCE10C6B8B15995606378CF281EEDD7515F0B4680181A75A08'){throw 'APM hash mismatch.'};Copy-Item $apm $clientOut -Force}
 Write-Host "PASS: PeerChat $version development build: $out"
} finally {Pop-Location}
